// ───────── Компактный конструктор примеров ─────────
const I = (rows) => rows.map(([icon, title, text = '', meta = '']) => it(icon, title, text, meta));
const FAQ = (rows) => rows.map(([q, a]) => it('message', q, a));

function mk(o) {
  const sections = [];
  sections.push(sec('features', o.features.nav ?? 'Услуги', o.features.title, { subtitle: o.features.sub ?? '', items: I(o.features.items) }));
  if (o.manifesto) sections.push(sec('manifesto', 'Подход', o.manifesto));
  sections.push(sec('about', 'О нас', o.about.title, { text: o.about.text, items: I(o.about.facts.map((f) => [f[0] ?? 'check', f[1] ?? f, f[2] ?? ''])) }));
  sections.push(sec('process', o.process.nav ?? 'Как работаем', o.process.title, { items: I(o.process.items) }));
  if (o.pricing) sections.push(sec('pricing', 'Цены', o.pricing.title, { subtitle: o.pricing.sub ?? 'Пример цен — в вашем сайте будут ваши.', items: I(o.pricing.items) }));
  sections.push(sec('faq', 'Вопросы', o.faqTitle ?? 'Частые *вопросы*', { items: FAQ(o.faq) }));
  sections.push(sec('cta', 'Связаться', o.cta.title, { text: o.cta.text, buttonLabel: o.cta.btn }));
  return {
    contact: { phone: '', email: '', address: '', hours: '', ...o.contact },
    content: {
      analysis: { businessType: o.type, audience: o.audience ?? '', positioning: o.tagline, tone: o.tone ?? 'уверенный', strengths: o.strengths ?? [] },
      brand: { name: o.name, tagline: o.tagline, language: 'ru', accent: o.accent, accent2: o.accent2 ?? o.accent },
      seo: { title: `${o.name} — ${o.tagline}`, description: o.sub },
      hero: {
        eyebrow: o.eyebrow, headline: o.headline, subheadline: o.sub, primaryCta: o.cta1, secondaryCta: o.cta2,
        highlights: I(o.hl), keywords: o.kw,
      },
      sections,
      contact: { navLabel: 'Контакты', title: o.contactTitle, subtitle: o.contactSub, buttonLabel: o.send ?? 'Отправить' },
      labels: LABELS,
    },
  };
}

